#include <stdio.h>
int maximum(int a, int b) {
 return a > b ? a : b;
}
int main(void) {
 int result = maximum(12, 9);
 printf("%d\n", result);
 return 0;
}

#include <stdio.h>
int is_even(int value) { return value % 2 == 0; }
int main(void) { printf("%s\n", is_even(8) ? "even" : "odd"); return 0; }
